CREATE TABLE IF NOT EXISTS workforce_team(team_id text PRIMARY KEY,name text NOT NULL UNIQUE,domain text NOT NULL,active boolean NOT NULL DEFAULT true,created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workforce_team_member(team_id text NOT NULL REFERENCES workforce_team(team_id),participant_id text NOT NULL REFERENCES application_participant(participant_id),active boolean NOT NULL DEFAULT true,joined_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(team_id,participant_id));
CREATE TABLE IF NOT EXISTS workforce_task(task_id text PRIMARY KEY,domain text NOT NULL,function_key text NOT NULL,required_capability text NOT NULL,title text NOT NULL,description text,state text NOT NULL DEFAULT 'OPEN' CHECK(state IN('OPEN','IN_PROGRESS','BLOCKED','DONE','CANCELLED')),created_by text NOT NULL REFERENCES application_participant(participant_id),created_at timestamptz NOT NULL DEFAULT now(),due_at timestamptz,completed_at timestamptz);
CREATE TABLE IF NOT EXISTS workforce_task_assignment(assignment_id text PRIMARY KEY,task_id text NOT NULL REFERENCES workforce_task(task_id),assignee_participant_id text REFERENCES application_participant(participant_id),assignee_team_id text REFERENCES workforce_team(team_id),assigned_by text NOT NULL REFERENCES application_participant(participant_id),assigned_at timestamptz NOT NULL DEFAULT now(),valid_until timestamptz,revoked_at timestamptz,CHECK((assignee_participant_id IS NOT NULL)::int+(assignee_team_id IS NOT NULL)::int=1));
CREATE INDEX IF NOT EXISTS workforce_task_assignment_task_idx ON workforce_task_assignment(task_id) WHERE revoked_at IS NULL;
-- Assignment is responsibility, never authority. APIs MUST verify required_capability against active application_authority_grant before accepting an assignee.
